<div x-data="{ open: false }"><button class="btn-muted" @click="open=true"><?= esc($trigger ?? 'Open confirmation') ?></button><div x-cloak x-show="open" class="fixed inset-0 z-50 grid place-items-center bg-gray-950/50 p-4" role="dialog" aria-modal="true" aria-labelledby="confirm-title"><div class="card w-full max-w-md p-6"><h2 id="confirm-title" class="text-lg font-semibold"><?= esc($title ?? 'Please confirm') ?></h2><p class="mt-2 text-sm text-gray-600"><?= esc($message ?? 'Are you sure you want to continue?') ?></p><div class="mt-6 flex justify-end gap-3"><button class="btn-muted" @click="open=false">Cancel</button><button class="btn-primary"><?= esc($confirmLabel ?? 'Confirm') ?></button></div></div></div></div>
